    P = int(data[2])

    idx = 3
    black_cells = set()
    for _ in range(P):
        r = int(data[idx])
        c = int(data[idx + 1])
        black_cells.add((r, c))
        idx += 2

    candidates = set()
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for r, c in black_cells:
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 1 <= nr <= L and 1 <= nc <= C:
                if (nr, nc) not in black_cells:
                    candidates.add((nr, nc))

    cand_list = list(candidates)
    cand_set = set(cand_list)

    # Divide candidates into two sets based on bipartite coloring
    # set_A: (r + c) % 2 == 0
    # set_B: (r + c) % 2 == 1
    adj = {}
    set_A = []
    for u in cand_list:
        if (u[0] + u[1]) % 2 == 0:
            set_A.append(u)
            adj[u] = []
            for dr, dc in dirs:
                v = (u[0] + dr, u[1] + dc)
                if v in cand_set:
                    adj[u].append(v)

    # Kuhn's algorithm for maximum bipartite matching
    match = {}

    def dfs(u, visited):
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                if v not in match or dfs(match[v], visited):
                    match[v] = u
                    return True
        return False

    max_matching = 0
    for u in set_A:
        visited = set()
        if dfs(u, visited):
            max_matching += 1

    ans = len(cand_list) - max_matching
    print(ans)


if __name__ == "__main__":
    solve()
